  "Stripe est l'une des plus grandes et des plus fiables sociétés de paiement au monde. Elle gère en toute sécurité les paiements en ligne de millions d'entreprises, du commerce de quartier à Amazon, Google et Shopify. Yuno utilise Stripe pour que vos clients paient en sécurité et que vous soyez payé de façon fiable.": "Stripe est l'une des plus grandes et des plus fiables sociétés de paiement au monde. Elle gère en toute sécurité les paiements en ligne de millions d'entreprises, du commerce de quartier à Amazon, Google et Shopify. Yuno utilise Stripe pour que vos clients paient en sécurité et que vous soyez payé de façon fiable.",
  "Stripe est un établissement de paiement agréé et réglementé en Europe et aux États-Unis, avec une sécurité de niveau bancaire (certifié PCI-DSS). Les données de carte sont chiffrées et ne passent jamais par Yuno.": "Stripe est un établissement de paiement agréé et réglementé en Europe et aux États-Unis, avec une sécurité de niveau bancaire (certifié PCI-DSS). Les données de carte sont chiffrées et ne passent jamais par Yuno.",
